
<template>

<div class="container" style="max-width: 400px; margin-top: 40px;"> <div class="card"> <h3 class="form-title">登录</h3> <p v-if="error" class="error">{{ error }}</p> <input v-model="form.username" placeholder="用户名" /> <input v-model="form.password" type="password" placeholder="密码" /> <button :disabled="loading" @click="submit"> {{ loading ? '登录中...' : '登录' }} </button> <p class="tip" style="margin-top: 12px;"> 没有账号？<router-link to="/register">去注册</router-link> </p> </div> </div> </template><script setup> import { reactive, ref } from 'vue'; import { useRoute, useRouter } from 'vue-router'; import { useUserStore } from '../stores/user'; const form = reactive({ username: '', password: '' }); const error = ref(''); const loading = ref(false); const store = useUserStore(); const router = useRouter(); const route = useRoute(); async function submit() { error.value = ''; if (!form.username || !form.password) { error.value = '请输入用户名和密码'; return; } loading.value = true; try { await store.login({ ...form }); router.push(route.query.redirect || '/home'); } catch (e) { error.value = e.message || '登录失败'; } finally { loading.value = false; } } </script>
